mapper.select:
SELECT COUNT(*)
FROM answer_record
WHERE user_id = #{userId}
  AND result = 1
  AND create_time >= #{start}
  AND create_time < #{end}

SELECT DATE(create_time) AS answer_date,
       COUNT(*) AS total_count,
       SUM(CASE WHEN result = 1 THEN 1 ELSE 0 END) AS correct_count
FROM answer_record
WHERE user_id = #{userId}
  AND create_time >= #{start}
  AND create_time < #{end}
GROUP BY DATE(create_time)
ORDER BY answer_date ASC
